"""Report imported names never referenced in the same module (simple AST check)."""
import ast, pathlib, sys
root = pathlib.Path(sys.argv[1])
skip = {".venv", ".claude", "__pycache__"}
found = 0
for path in sorted(root.rglob("*.py")):
    if skip & set(path.parts):
        continue
    tree = ast.parse(path.read_text())
    imported = {}
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for a in node.names:
                imported[(a.asname or a.name).split(".")[0]] = node.lineno
        elif isinstance(node, ast.ImportFrom):
            for a in node.names:
                imported[a.asname or a.name] = node.lineno
    used = {n.id for n in ast.walk(tree) if isinstance(n, ast.Name)} | \
           {n.value.id for n in ast.walk(tree) if isinstance(n, ast.Attribute) and isinstance(n.value, ast.Name)}
    for name, line in imported.items():
        if name not in used and not path.name == "__init__.py" and name != "models":
            print(f"{path.relative_to(root)}:{line} unused import {name}")
            found += 1
print("unused imports:", found)

